WebLink.url:
/************************************************************************************
Button   :  RedAlertFlag
Developer:  Mickey Murphy, Blue Wolf Group LLC
Created  :  June 27, 2013
Modified :  July 10, 2013
Objective:  This script sets [Account.At_Risk_Score__c] to 10.

************************************************************************************/

{!REQUIRESCRIPT("/soap/ajax/28.0/connection.js")}

var accounts = [];
var account  = new sforce.SObject("Account");

account.At_Risk_Score__c = 10;
account.Id = "{!Account.Id}";
account.Red_Alert_Flag__c = true;

accounts.push (account); 
result = sforce.connection.update(accounts); 
window.top.location = "/apex/ManualRiskAssessmentPage?id={!Account.Id}";
